const url = 'https://coolors.co/e63946-f1faee-a8dadc-457b9d-1d3557';
let COLORS = [];

const cellsize = 40;
let cellW, cellH;
let thetarate, moverate;

let cells = [];
let originx, originy;


function setup() {
  createCanvas(windowWidth, windowHeight);
  background(220);

  COLORS = extractColors(url);


  cellH = cellsize;
  cellW = cellH * sqrt(2);
  thetarate = 1 / 240;
  moverate = cellH * 0.04;

  originx = width / 2;
  originy = height / 2;

  let num = floor(height / (cellsize * 4));

  for (let j = 0; j <= num; j++) {
    for (let i = 0; i <= num; i++) {
      let cellsquare = new CellSquare(i, j);
			cellsquare.show();
      cells.push(cellsquare);
    }
  }
}

function draw() {
  // background(220);

  for (let cell of cells) {
    if (!cell.isDone()) {
      cell.update();
      cell.show();
    }
  }
}


class Epoint {
  constructor(theta) {
    this.theta = theta;

    this.initialize();
  }

  initialize() {
    let r = cellW * cellH / sqrt(pow(cellH * cos(this.theta), 2) + pow(cellW * sin(this.theta), 2));
    this.x = r * cos(this.theta);
    this.y = r * sin(this.theta);
  }

  update() {
    let r = cellW * cellH / sqrt(pow(cellH * cos(this.theta), 2) + pow(cellW * sin(this.theta), 2));
    this.x = r * cos(this.theta);
    this.y = r * sin(this.theta);

    this.theta += thetarate * PI;
  }

  tangential() {
    let tx = cellW * cellH / this.x;
    let ty = cellW * cellH / this.y;
    noFill();
    stroke(255);
    line(tx, 0, 0, ty);
    noStroke();
    fill(255, 0, 0);
    ellipse(this.x, this.y, 10);
  }

}

class CellSquare {
  constructor(col, row) {
    this.col = col;
    this.row = row;

    this.color = color(random(COLORS));
    // this.color.setAlpha(10);

    this.eps = [];
    this.tps = [];

    this.turn = floor(height/400); //floor(random(1, 5));
    this.pause = (col+row)*15;
    this.count = 0;

    this.initialize();
  }

  initialize() {
    for (let i = 0; i < 4; i++) {
      this.eps.push(new Epoint(i * PI / 2 - PI / 4));
    }

    let w = this.crosspoint(this.eps[0], this.eps[1]).x;
    let h = this.crosspoint(this.eps[1], this.eps[2]).y;

    this.x = originx + (this.col - this.row) * w;
    this.y = originy + (this.col + this.row) * h;

		for (let i = 0; i < this.eps.length; i++) {
      if (i === 3) {
        this.tps[i] = this.crosspoint(this.eps[i], this.eps[0]);
      } else {
        this.tps[i] = this.crosspoint(this.eps[i], this.eps[i + 1]);
      }
      this.tps[i].add(createVector(this.x, this.y));
    }
  }

  update() {
    if(this.count < this.pause) {
      this.count++;
    } else {
      for (let ep of this.eps) {
        ep.update();
      }

      for (let i = 0; i < this.eps.length; i++) {
        if (i === 3) {
          this.tps[i] = this.crosspoint(this.eps[i], this.eps[0]);
        } else {
          this.tps[i] = this.crosspoint(this.eps[i], this.eps[i + 1]);
        }
        this.tps[i].add(createVector(this.x, this.y));
      }

      this.y -= moverate;
      this.turn -= thetarate * 2;
    }
  }

  crosspoint(p1, p2) {
    let x1 = p1.x;
    let y1 = p1.y;
    let x2 = p2.x;
    let y2 = p2.y;

    let x = cellW * cellW * (y1 - y2) / (x2 * y1 - x1 * y2);
    let y = cellH * cellH * (x1 - x2) / (x1 * y2 - x2 * y1);

    return createVector(x, y);
  }

  show() {
    stroke(0, 120);
    // strokeWeight(2);
    fill(this.color);
    beginShape();
    for (let tp of this.tps) {
      vertex(tp.x, tp.y);
    }
    endShape(CLOSE);
  }

  isDone() {
    return this.turn < 0 ? true : false;
  }
}



function extractColors(url) {
  let lastslash = url.lastIndexOf('/');
  let sliced = url.slice(lastslash + 1);
  let cols = sliced.split('-');
  let newcols = [];
  for (let col of cols) {
    newcols.push('#' + col);
  }
  return newcols;
}

